private GridBand GetBandForColumn(string colName,
    GridBand gbTeacher, GridBand gbExam, GridBand gbStandard,
    GridBand gbCV, GridBand gbNCKH, GridBand gbTeaching)
{
    string upper = colName.ToUpper();

    // GIẢNG VIÊN
    if (upper.Contains("TEACHERID")
        || upper.Contains("TEACHERFIRSTNAME")
        || upper.Contains("TEACHERLASTNAME")
        || upper.Contains("TEACHERNAME")
        || colName == "TeacherName")
        return gbTeacher;

    // COI THI / CHẤM THI
    if (upper.Contains("COITHI")
        || upper.Contains("CHAMTHI")
        || upper.Contains("GIOQUYDOI_COITHI")
        || upper.Contains("GIOQUYDOI_CHAMTHI")
        || upper.Contains("SOGIO_COITHI")
        || upper.Contains("SOBAI_CHAMTHI"))
        return gbExam;

    // GIỜ CHUẨN / KIÊM NHIỆM
    if (upper.Contains("STANDARDQUANTITY")
        || upper.Contains("RATIOPOSITION")
        || upper.Contains("REALSTANDARDQUANTITY")
        || upper.Contains("DINHMUC"))
        return gbStandard;

    // CV HỌC TẬP / HOẠT ĐỘNG KHÁC
    if (upper.Contains("W34")
        || upper.Contains("W35")
        || upper.Contains("HOCTAP")
        || upper.Contains("BOIDUONG")
        || upper.Contains("HOATDONG"))
        return gbCV;

    // NCKH
    if (upper.Contains("NCKH")
        || upper.Contains("RESEARCH"))
        return gbNCKH;

    // GIẢNG DẠY THỰC TẾ (mặc định)
    return gbTeaching;
}

