private void BuildSummaryCollection()
{
    System.Text.StringBuilder sb = new System.Text.StringBuilder();

    foreach (DataColumn dc in dtbData.Columns)
    {
        string upper = dc.ColumnName.ToUpper();

        // Chỉ tính tổng cho các cột số
        if (dc.DataType == typeof(decimal)
            || dc.DataType == typeof(double)
            || dc.DataType == typeof(int)
            || dc.DataType == typeof(long)
            || dc.DataType == typeof(float))
        {
            // Bỏ qua TeacherID và các cột ID
            if (upper == "TEACHERID")
                continue;

            if (sb.Length > 0)
                sb.Append(",");
            sb.Append(dc.ColumnName);
        }
    }

    gvData.SummaryCollection = sb.ToString();
}

private void AddComputedColumns()
{
    // Kiểm tra các cột nguồn tồn tại
    string[] requiredCols = {
        "RealStandardQuantity_DinhMucGiangDayNamHoc",
        "TotalFinal_W34_HocTapBoiDuong",
        "TotalFinal_W35_HoatDongKhac",
        "ResearchNow_NCKH",
        "TongLTTH"
    };

    foreach (string col in requiredCols)
    {
        if (!dtbData.Columns.Contains(col))
            return;
    }

    // Cột 1: Tổng cộng tất cả
    // = ĐM GD năm học + HT bồi dưỡng + HĐ khác + NCKH + Tổng LT+TH
    if (!dtbData.Columns.Contains("TongCongTatCa"))
    {
        dtbData.Columns.Add("TongCongTatCa", typeof(decimal),
            "ISNULL(RealStandardQuantity_DinhMucGiangDayNamHoc, 0) + ISNULL(TotalFinal_W34_HocTapBoiDuong, 0) + ISNULL(TotalFinal_W35_HoatDongKhac, 0) + ISNULL(ResearchNow_NCKH, 0) + ISNULL(TongLTTH, 0)");
    }

    // Cột 2: Tổng ĐM + NCKH
    // = ĐM GD năm học + NCKH
    if (!dtbData.Columns.Contains("TongDinhMucVaNCKH"))
    {
        dtbData.Columns.Add("TongDinhMucVaNCKH", typeof(decimal),
            "ISNULL(RealStandardQuantity_DinhMucGiangDayNamHoc, 0) + ISNULL(ResearchNow_NCKH, 0)");
    }

    // Cột 3: Vượt tối thiểu = Tổng cộng tất cả - Tổng ĐM+NCKH
    if (!dtbData.Columns.Contains("VuotToiThieu"))
    {
        dtbData.Columns.Add("VuotToiThieu", typeof(decimal),
            "ISNULL(TongCongTatCa, 0) - ISNULL(TongDinhMucVaNCKH, 0)");
    }
}

