private void ShowChiTietTongSoGio(DataRow drw)
{
    decimal dDinhMuc = GetDecimal(drw, "RealStandardQuantity_DinhMucGiangDayNamHoc");
    decimal dHTBD = GetDecimal(drw, "TotalFinal_W34_HocTapBoiDuong");
    decimal dHDKhac = GetDecimal(drw, "TotalFinal_W35_HoatDongKhac");
    decimal dNCKH = GetDecimal(drw, "ResearchNow_NCKH");
    decimal dTongLTTH = GetDecimal(drw, "TongLTTH");
    decimal dCoiThi = GetDecimal(drw, "GioQuyDoi_CoiThi");
    decimal dChamThi = GetDecimal(drw, "GioQuyDoi_ChamThi");
    decimal dSoanDe = GetDecimal(drw, "SoGioSoanDe");
    decimal dTong = dDinhMuc + dHTBD + dHDKhac + dNCKH + dTongLTTH + dCoiThi + dChamThi + dSoanDe;

    string message =
        "╔══════════════════════════════════════╗\n" +
        "║     CHI TIẾT TỔNG SỐ GIỜ GIẢNG DẠY, HOẠT ĐỘNG     ║\n" +
        "╠══════════════════════════════════════╣\n" +
        String.Format("║  Định mức GD năm học   : {0,10:N2}  ║\n", dDinhMuc) +
        String.Format("║  HT, bồi dưỡng         : {0,10:N2}  ║\n", dHTBD) +
        String.Format("║  HĐ khác               : {0,10:N2}  ║\n", dHDKhac) +
        String.Format("║  NCKH                  : {0,10:N2}  ║\n", dNCKH) +
        String.Format("║  Tổng LT+TH            : {0,10:N2}  ║\n", dTongLTTH) +
        String.Format("║  Giờ QĐ coi thi        : {0,10:N2}  ║\n", dCoiThi) +
        String.Format("║  Giờ QĐ chấm thi       : {0,10:N2}  ║\n", dChamThi) +
        String.Format("║  Giờ soạn đề           : {0,10:N2}  ║\n", dSoanDe) +
        "╠══════════════════════════════════════╣\n" +
        String.Format("║  TỔNG CỘNG            : {0,10:N2}  ║\n", dTong) +
        "╚══════════════════════════════════════╝";

    MessageManager.Information(message);
}

private decimal GetDecimal(DataRow drw, string columnName)
{
    if (drw.Table.Columns.Contains(columnName))
    {
        object val = drw[columnName];
        if (val != DBNull.Value && val != null)
        {
            decimal result;
            if (decimal.TryParse(val.ToString(), out result))
                return result;
        }
    }
    return 0m;
}

